import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2022-11-03","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-11-03","date":"2022-11-03T00:00:00.000Z","updated":"2022-11-10T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","蓝鲸存储","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-11-03.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-11-03.md","lastUpdated":1780460162000}'),i={name:"posts/2022/Ceph_Performance_Meeting_2022-11-03.md"};function o(n,e,s,h,u,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了Ceph分布式存储系统的性能问题，包括librbd与qemu-kvm的性能差距、RBD镜像的性能问题以及Blue Store的优化方向。会议涉及了多个技术议题，如性能调优、加密影响、快照性能、Blue Store的未来发展等。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>librbd与qemu-kvm性能差距</strong></p><ul><li>讨论了librbd与qemu-kvm性能差距，实验结果显示，启用加密时，性能下降约30%，主要原因是加密处理占用了大量messenger线程时间。</li></ul></li><li><p><strong>RBD镜像性能问题</strong></p><ul><li>分析了RBD镜像性能下降的原因，如快照和快照修剪导致的OSD使用率上升。</li><li>讨论了对象碎片化和共享blob问题，并提出了解决方案。</li></ul></li><li><p><strong>Blue Store的优化方向</strong></p><ul><li>讨论了Blue Store的未来发展方向，包括可能的Blue Store 2版本。</li><li>讨论了改进写路径、处理分层存储等方向。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续测试和优化RBD镜像的性能问题。</li><li>对于Blue Store的优化，考虑是否进行大的架构改变。</li><li>进行更多实验和测试，确定最佳性能调优方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续跟踪和优化RBD镜像的性能问题。</li><li>对Blue Store的优化进行更多讨论和实验。</li><li>进行更多性能测试，确定最佳性能调优方案。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了Blue Store的写路径优化。</li><li>讨论了如何更好地利用不同的存储设备。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本次会议深入讨论了Ceph存储系统的性能问题，并提出了相应的解决方案和优化方向。后续将继续进行更多的测试和优化工作，以提高系统的性能和稳定性。</p>',13)])])}const _=a(i,[["render",o]]);export{c as __pageData,_ as default};
